java:invoke-static.java:args:
#[{
	text: payload.WSResponseBody,
	ivBase64: vars.x_civ_response,
	secret: vars.secret.secret
}]

set-variable.value:
#[%dw 2.0
output text/plain
---
write({
	"Audit": {
		"Canal": vars.headers.name
	},
	"Billing_Address": payload.billingAddress,
  	"Delivery_Address": {
	    "Address": payload.deliveryAddress.address,
	    "City": payload.deliveryAddress.city,
	    "City_DANE": payload.deliveryAddress.cityDane,
	    "Department": payload.deliveryAddress.department,
	    "Department_DANE": payload.deliveryAddress.departmentDane,
	    "District": payload.deliveryAddress.district
  },
	"Delivery_Type": payload.deliveryType,
	"Delivery_Invoice_Type": payload.deliveryInvoiceType,
	"Order_Number": payload.orderNumber
},
"application/json"
)]

#[%dw 2.0
output text/plain
---
write({
  Audit: {
    Canal: vars.headers.name
  },
  Order_Number: payload.orderNumber,
  Attributes: payload.attributes map (item) -> {
    Attribute: item.attribute,
    Value: item.value
  }
},
"application/json"
)]

#[%dw 2.0
output text/plain
var operation = vars.variablesRequest.operation
---
write({
	"Audit": {
		"Canal": vars.headers.name
	} filterObject ((value, key) -> value != null),

	"Customer": {
		"Document_Number": payload.customer.documentNumber,
		"Document_Type": payload.customer.documentType
	} filterObject ((value, key) -> value != null),

	"Plan": payload.order.lte.plan,
	"Portability": payload.order.lte.Portability,
	"Preactive_Sims": payload.order.lte.Preactive_Sims,
	"SVAs": payload.order.lte.svas
} filterObject ((value, key) -> value != null),
"application/json"
)]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  status: 400,
  code: "INVALID_FIELD",
  message: {
    message: "The field 'flow' must be LTE or FTTH"
  },
  messageServer: "Validation error: unsupported value in field 'flow'. Expected [LTE, FTTH]."
}
